DE( count(DISTINCT CASE WHEN lower(return_type) = \'rto\' THEN ordeR_id END) + count(DISTINCT CASE WHEN lower(return_type) = \'return\' THEN ordeR_id END), count(DISTINCT order_id) ) AS `overall_return_rate` FROM `MapleMonk`.`izf_returns_consolidated` WHERE order_date >= DATE_ADD(CURRENT_DATE(), INTERVAL -37 DAY) AND order_date < DATE_ADD(CURRENT_DATE(), INTERVAL -7 DAY) GROUP BY 1 ) r on lower(a.sku_style) = lower(r.sku_style) left join ( select sku_style, sku_size, sum(ifnull(Available_Inventory,0)) Available_Inventory from maplemonk.izf_inventory_fact_items where date_diff(current_date(),data_fetch_date,DAY) = 1 group by 1,2 ) i on lower(a.sku_style) = lower(i.sku_style) and lower(a.sku_size) = lower(i.sku_size) left join (select Brand, date_trunc(date(COALESCE(SAFE.PARSE_DATE(\'%Y-%m-%d\', week), SAFE.PARSE_DATE(\'%d-%m-%Y\', week), SAFE.PARSE_DATE(\'%Y-%d-%m\', week))), week(monday)) as order_week, cast(ctr__ as float64)/100 as ctr, Gender, cast(avg_RPLC as float64)/100 as avg_RPLC, cast(ATC_rate__ as float64)/100 as ATC_rate, sa.Article_Type, SPLIT(mm.Article_no, \'-\')[OFFSET(0)] as Style, cast(total_clicks as int64) Clicks, cast(avg_Seller_MRP as int64) avg_Seller_MRP, cast(total_purchases as int64) total_purchases, cast(Conversion_rate__ as float64)/100 as Conversion_Rate, cast(total_impressions as int64) total_impressions, cast(total_add_to_carts as int64) total_add_to_carts, cast(Return___weighted as float64)/100 as Return_percent from maplemonk.gs_myntra_search_analytics sa left join maplemonk.gs_myntra_sku_mapping mm on replace(mm.style_id,\' \',\'\') = cast(sa.style_id as string) ) sa on lower(a.sku_style) = lower(sa.style) and sa.order_week = date_trunc(date(a.date_day), week(monday)) group by 1,2,3,4;",
